package com.opentv.app.util;
import android.graphics.*;import android.os.*;import android.util.LruCache;import android.widget.ImageView;import java.io.InputStream;import java.net.*;import java.util.concurrent.*;
public final class LogoLoader {private static final LruCache<String,Bitmap>CACHE=new LruCache<>(80);private static final ExecutorService EX=Executors.newFixedThreadPool(4);private static final Handler MAIN=new Handler(Looper.getMainLooper());private LogoLoader(){}
public static void load(ImageView v,String u){v.setImageResource(android.R.color.transparent);v.setTag(u);if(u==null||u.trim().isEmpty())return;Bitmap b=CACHE.get(u);if(b!=null){v.setImageBitmap(b);return;}EX.execute(()->{Bitmap x=download(u);if(x!=null)CACHE.put(u,x);MAIN.post(()->{if(x!=null&&u.equals(v.getTag()))v.setImageBitmap(x);});});}
private static Bitmap download(String s){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(s).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setRequestProperty("User-Agent","OpenTV/1.1 AndroidTV");c.connect();if(c.getResponseCode()<200||c.getResponseCode()>=300)return null;try(InputStream in=c.getInputStream()){return BitmapFactory.decodeStream(in);}}catch(Exception e){return null;}finally{if(c!=null)c.disconnect();}}}
